"use client";

import { useEffect, useRef } from "react";

interface AdSenseSlotProps {
  clientId: string;
  slotId?: string;
  className?: string;
  format?: "auto" | "rectangle" | "horizontal" | "vertical";
  responsive?: boolean;
}

declare global {
  interface Window {
    adsbygoogle?: Array<Record<string, unknown>>;
  }
}

/**
 * AdSenseSlot — Production-safe Google AdSense Container
 *
 * Responsively renders Google AdSense `<ins>` tag and initializes
 * the Google runtime via `adsbygoogle.push({})` on mount.
 *
 * Protections:
 * - Duplicate initialization guard prevents crashes during React strict mode and SPA transitions.
 * - `try/catch` wrapper absorbs adblocker and network error exceptions.
 * - Zero raw HTML injection or fake advertisements.
 */
export default function AdSenseSlot({
  clientId,
  slotId,
  className = "my-8 text-center",
  format = "auto",
  responsive = true,
}: AdSenseSlotProps) {
  const initialized = useRef(false);

  useEffect(() => {
    if (initialized.current) return;

    try {
      if (typeof window !== "undefined") {
        (window.adsbygoogle = window.adsbygoogle || []).push({});
        initialized.current = true;
      }
    } catch (err) {
      console.warn("[AdSenseSlot] Non-fatal initialization warning:", err);
    }
  }, []);

  if (!clientId || typeof clientId !== "string" || clientId.trim() === "") {
    return null;
  }

  return (
    <div className={className}>
      <ins
        className="adsbygoogle"
        style={{ display: "block" }}
        data-ad-client={clientId.trim()}
        data-ad-slot={slotId?.trim() || undefined}
        data-ad-format={format}
        data-full-width-responsive={responsive ? "true" : "false"}
      />
    </div>
  );
}
