interface ValidFaqItem {
  question: string;
  answer: string;
}

function getValidFaqs(rawFaq: unknown): ValidFaqItem[] {
  if (!Array.isArray(rawFaq)) return [];
  const valid: ValidFaqItem[] = [];
  for (const item of rawFaq) {
    if (!item || typeof item !== "object") continue;
    const candidate = item as Record<string, unknown>;
    const q = typeof candidate.question === "string" ? candidate.question.trim() : "";
    const a = typeof candidate.answer === "string" ? candidate.answer.trim() : "";
    if (q.length > 0 && a.length > 0) {
      valid.push({ question: q, answer: a });
    }
  }
  return valid;
}

