// ── Data Fetching Helper with Cancellation Enrichment ─────────────────────────

async function getArticleData(slug: string): Promise<{ article: NewsArticle; related: NewsArticle[] } | null> {
  try {
    const res = await fetch(`${API_HOST}/api/news/${encodeURIComponent(slug)}`, {
      next: { revalidate: 1800 },
    }).catch(() => null);

    if (!res || !res.ok) return null;

    const json = await res.json();
    if (!json.success || !json.data) return null;

    const article: NewsArticle = json.data;

    // Enrich cancellation details if this is a cancellation advisory
    if (article.category === "Cancellation" || slug.startsWith("cancelled-diverted-trains-")) {
      try {
        const slugDateMatch = slug.match(/cancelled-diverted-trains-(\d{4}-\d{2}-\d{2})/);
        const cancelUrl = slugDateMatch
          ? `${API_HOST}/api/trains/cancellations/today?date=${slugDateMatch[1]}`
          : `${API_HOST}/api/trains/cancellations/today`;

        const cancelRes = await fetch(cancelUrl, {
          signal: AbortSignal.timeout(4000),
          next: { revalidate: 900 },
        }).catch(() => null);
        if (cancelRes && cancelRes.ok) {
          const cancelJson = await cancelRes.json();
          if (cancelJson.success && cancelJson.data) {
            const feed = cancelJson.data;
            const trainMap = new Map<string, ImpactedTrainDetail>();

            for (const t of feed.fullyCancelledTrains || []) {
              const no = String(t.trainNo || "").trim();
              if (no) trainMap.set(no, { ...t, status: "fully_cancelled" });
            }
            for (const t of feed.partiallyCancelledTrains || []) {
              const no = String(t.trainNo || "").trim();
              if (no) trainMap.set(no, { ...t, status: "partially_cancelled" });
            }

            const enrichedList: ImpactedTrainDetail[] = [];
            const seenNos = new Set<string>();

            // First include article's affected trains
            if (Array.isArray(article.affectedTrains)) {
              for (const item of article.affectedTrains) {
                const no = String(item).trim();
                if (!no) continue;
                seenNos.add(no);
                if (trainMap.has(no)) {
                  enrichedList.push(trainMap.get(no)!);
                } else {
                  enrichedList.push({
                    trainNo: no,
                    trainName: `Express ${no}`,
                    status: "fully_cancelled",
                    route: null,
                    cancelledSegment: null,
                  });
                }
              }
            }

            // Include any remaining from live cancellation feed
            for (const [no, detail] of trainMap.entries()) {
              if (!seenNos.has(no)) {
                seenNos.add(no);
                enrichedList.push(detail);
              }
            }

            if (enrichedList.length > 0) {
              article.affectedTrainsDetail = enrichedList;
            }
          }
        }
      } catch (enrichErr) {
        console.warn("[NewsArticlePage] Non-blocking cancellation enrichment notice:", enrichErr);
      }
    }

    // Enrich special train details if this is a special train announcement
    if (article.category === "Special Trains" || slug.startsWith("special-festival-trains-")) {
      try {
        const specialUrl = `${API_HOST}/api/trains/special-trains/today`;
        const specialRes = await fetch(specialUrl, {
          signal: AbortSignal.timeout(4000),
          next: { revalidate: 900 },
        }).catch(() => null);

        if (specialRes && specialRes.ok) {
          const specialJson = await specialRes.json();
          if (specialJson.success && Array.isArray(specialJson.data?.trains)) {
            article.affectedTrainsDetail = specialJson.data.trains.map((t: any) => ({
              trainNo: t.trainNo,
              trainName: t.trainName,
              status: "special_service",
              route: null,
              cancelledSegment: null,
            }));
          }
        }
      } catch (specialErr) {
        console.warn("[NewsArticlePage] Non-blocking special trains enrichment notice:", specialErr);
      }
    }

    return {
      article,
      related: json.related || [],
    };
  } catch (err) {
    console.error(`[NewsArticlePage] Failed to fetch article: ${slug}`, err);
    return null;
  }
}

// ── SERP Formatting Helpers ───────────────────────────────────────────────────

function formatSerpTitle(rawTitle: string | null | undefined): string {
  if (!rawTitle || typeof rawTitle !== "string") {
    return "Trayago Railway News";
  }
  const clean = rawTitle.replace(/\s*\|\s*Trayago(\s*News)?$/i, "").trim();
  if (!clean) {
    return "Trayago Railway News";
  }

  const BRAND = " | Trayago";
  const withBrand = `${clean}${BRAND}`;
  if (withBrand.length <= 60) {
    return withBrand;
  }

  // When clean + BRAND > 60 chars, allocate up to 50 chars for the headline prefix
  const maxPrefixLen = 60 - BRAND.length; // 50
  const candidate = clean.slice(0, maxPrefixLen);

  // If character at maxPrefixLen is a space, or candidate ends with space,
  // then the first 50 chars end cleanly on a word boundary
  if (clean[maxPrefixLen] === " " || candidate.endsWith(" ")) {
    const trimmed = candidate.trim().replace(/[,;&:\-\s]+$/, "");
    if (trimmed.length > 0) {
      return `${trimmed}${BRAND}`;
    }
  }

  // Otherwise, position 50 cut a word. Find the last space to avoid cutting words in half.
  const lastSpace = candidate.lastIndexOf(" ");
  if (lastSpace > 0) {
    const trimmed = candidate.slice(0, lastSpace).trim().replace(/[,;&:\-\s]+$/, "");
    if (trimmed.length > 0) {
      return `${trimmed}${BRAND}`;
    }
  }

  // Unbroken token / single word > 50 chars where no word boundary exists:
  // Safely truncate the headline portion to 50 chars so headlinePrefix + " | Trayago" <= 60
  const trimmed = candidate.trim().replace(/[,;&:\-\s]+$/, "");
  return `${trimmed || candidate.trim()}${BRAND}`;
}

function formatSerpDescription(rawDesc: string | null | undefined): string {
  const fallback = "Official Indian Railways update and passenger travel guidance.";
  if (!rawDesc || typeof rawDesc !== "string") {
    return fallback;
  }
  const clean = rawDesc.replace(/\s+/g, " ").trim();
  if (!clean) {
    return fallback;
  }

  const maxLen = 155;
  if (clean.length <= maxLen) {
    return clean.replace(/[,;&:\-\s(]+$/, "");
  }

  const candidate = clean.slice(0, maxLen);

  // If character at maxLen is space or candidate ends with space, word boundary is clean
  if (clean[maxLen] === " " || candidate.endsWith(" ")) {
    const trimmed = candidate.trim().replace(/[,;&:\-\s(]+$/, "");
    if (trimmed.length > 0) {
      return trimmed;
    }
  }

  // Otherwise position 155 cut a word. Find the last space to avoid cutting word in half.
  const lastSpace = candidate.lastIndexOf(" ");
  if (lastSpace > 0) {
    const trimmed = candidate.slice(0, lastSpace).trim().replace(/[,;&:\-\s(]+$/, "");
    if (trimmed.length > 0) {
      return trimmed;
    }
  }

  return candidate.trim().replace(/[,;&:\-\s(]+$/, "");
}

const SAFE_RAILWAY_COVER_FALLBACK = "https://www.trayago.in/og-image.png";

const BANNED_IMAGE_PATTERNS = [
  /photo-1544620347/i, // Bus image incorrectly mapped to Vande Bharat
  /photo-1509749837/i, // Unverified generic dark passenger car interior
];

function resolveSafeArticleImageUrl(imageUrl?: string | null): string {
  if (!imageUrl || typeof imageUrl !== "string" || !imageUrl.trim().startsWith("http")) {
    return SAFE_RAILWAY_COVER_FALLBACK;
  }
  const clean = imageUrl.trim();
  if (BANNED_IMAGE_PATTERNS.some((pat) => pat.test(clean))) {
    return SAFE_RAILWAY_COVER_FALLBACK;
  }
  if (clean.includes("branding/og-image.png") || clean.includes("trayago.in/branding")) {
    return SAFE_RAILWAY_COVER_FALLBACK;
  }
  return clean;
}

function getArticleImageAlt(imageUrl: string | null | undefined, title: string): string {
  if (!imageUrl) {
    return `Route illustration and travel guidance for ${title}`;
  }
  if (imageUrl.includes("og-image.png") || imageUrl.includes("branding")) {
    return `Trayago Railway Guide: Route overview and travel guidance for ${title}`;
  }
  return `Editorial illustration and travel guide overview for ${title}`;
}

// ── Dynamic SEO Metadata ──────────────────────────────────────────────────────

export async function generateMetadata(props: PageProps): Promise<Metadata> {
  const params = await props.params;
  const slug = params.slug;
  const data = await getArticleData(slug);

  if (!data || !data.article) {
    return {
      title: "Article Not Found | Trayago Railway News",
      description: "The requested railway news article could not be found or is no longer available.",
      robots: {
        index: false,
        follow: false,
      },
    };
  }

  const { article } = data;
  const cleanSlug = String(article.slug || slug || "").trim().toLowerCase().replace(/^\/+|\/+$/g, "");
  const canonicalUrl = `https://www.trayago.in/news/${cleanSlug}`;
  const rawTitle = article.seoTitle || article.title || "";
  const title = formatSerpTitle(rawTitle);
  const rawDesc = article.metaDescription || article.summary || "";
  const description = formatSerpDescription(rawDesc);
  const ogImage = resolveSafeArticleImageUrl(article.imageUrl);

  const trainNamesKeywords = (article.affectedTrainsDetail || [])
    .slice(0, 15)
    .map((t) => `${t.trainNo} ${t.trainName || ""}`.trim())
    .filter(Boolean);

  return {
    title,
    description,
    keywords: [
      article.category,
      ...trainNamesKeywords,
      ...(article.affectedTrains?.map((t) => `Train ${t}`) || []),
      ...(article.affectedStations || []),
      "Indian Railways news",
      "IRCTC updates",
      "Cancelled trains list",
      "Diverted trains",
      "Trayago news",
    ].filter(Boolean).join(", "),
    alternates: {
      canonical: canonicalUrl,
      languages: {
        "en-IN": canonicalUrl,
        "hi-IN": `${canonicalUrl}?lang=hi`,
        "x-default": canonicalUrl,
      },
    },
    robots: {
      index: true,
      follow: true,
      googleBot: {
        index: true,
        follow: true,
        "max-video-preview": -1,
        "max-image-preview": "large",
        "max-snippet": -1,
      },
    },
    openGraph: {
      type: "article",
      title,
      description,
      url: canonicalUrl,
      siteName: "Trayago",
      publishedTime: article.publishedAt,
      modifiedTime: article.updatedAt || article.publishedAt,
      section: article.category,
      images: [{ url: ogImage, width: 1200, height: 630, alt: getArticleImageAlt(ogImage, article.title) }],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [ogImage],
    },
  };
}

